func TestP2PNode(t *testing.T) {
	ctx := context.Background()
	sk, err := ParsePriv(params.ChainAuths[0].Key)
	assert.NoError(t, err)

	idB, err := peer.IDFromPublicKey(sk.GetPublic())
	assert.NoError(t, err)

	staticPeer := fmt.Sprintf("/ip4/%s/tcp/%d/p2p/%s", "192.168.0.198", PreconfP2pPort, idB)
	p2pNode, err := NewP2PNode(ctx, rpccli, staticPeer)
	assert.NoError(t, err)
	defer p2pNode.Close()
	assert.NoError(t, p2pNode.WaitConnected(ctx, time.Minute))

	var bodies0 = make([]*eth.ExecutionPayloadEnvelope, 0)
	var bodies1 = make([]*eth.ExecutionPayloadEnvelope, 0)
	assert.NoError(t, json.Unmarshal([]byte(data0), &bodies0))
	assert.NoError(t, json.Unmarshal([]byte(data1), &bodies1))

	var (
		bodies0Map = make(map[common.Hash]*eth.ExecutionPayloadEnvelope)
		bodies1Map = make(map[common.Hash]*eth.ExecutionPayloadEnvelope)
	)
	for _, body := range bodies0 {
		bodies0Map[body.ExecutionPayload.BlockHash] = body
		t.Log("bodies0 content", "number", uint64(body.ExecutionPayload.BlockNumber), "hash", body.ExecutionPayload.BlockHash)
	}

	for _, body := range bodies1 {
		bodies1Map[body.ExecutionPayload.BlockHash] = body
		t.Log("bodies1 content", "number", uint64(body.ExecutionPayload.BlockNumber), "hash", body.ExecutionPayload.BlockHash)
	}

	bodies0 = append(bodies0, bodies1...)
	rand.New(rand.NewSource(time.Now().UnixNano()))
	rand.Shuffle(len(bodies0), func(i, j int) {
		bodies0[i], bodies0[j] = bodies0[j], bodies0[i]
	})

	//data, err := json.Marshal(bodies0)
	//assert.NoError(t, err)
	//assert.NoError(t, os.WriteFile("preconf_blocks.json", data, 0644))

	for _, msg := range bodies0 {
		if bodies0Map[msg.ExecutionPayload.BlockHash] != nil {
			log.Info("bodies0 message", "number", uint64(msg.ExecutionPayload.BlockNumber), "hash", msg.ExecutionPayload.BlockHash.TerminalString(), "parent", msg.ExecutionPayload.ParentHash.TerminalString())
		} else if bodies1Map[msg.ExecutionPayload.BlockHash] != nil {
			log.Info("bodies1 message", "number", uint64(msg.ExecutionPayload.BlockNumber), "hash", msg.ExecutionPayload.BlockHash.TerminalString(), "parent", msg.ExecutionPayload.ParentHash.TerminalString())
		} else {
			t.Logf("------------------------------")
		}
		assert.NoError(t, p2pNode.PublishL2Payload(ctx, msg))
		time.Sleep(time.Second / 10)
	}
	t.Logf("==============================")
}

func TestDD(t *testing.T) {
	ctx := context.Background()
	sk, err := ParsePriv(params.ChainAuths[0].Key)
	assert.NoError(t, err)

	idB, err := peer.IDFromPublicKey(sk.GetPublic())
	assert.NoError(t, err)

	staticPeer := fmt.Sprintf("/ip4/%s/tcp/%d/p2p/%s", "192.168.0.198", PreconfP2pPort, idB)
	p2pNode, err := NewP2PNode(ctx, rpccli, staticPeer)
	assert.NoError(t, err)
	defer p2pNode.Close()
	assert.NoError(t, p2pNode.WaitConnected(ctx, time.Minute))

	var bodies0 = make([]*eth.ExecutionPayloadEnvelope, 0)
	var bodies1 = make([]*eth.ExecutionPayloadEnvelope, 0)
	assert.NoError(t, json.Unmarshal([]byte(data0), &bodies0))
	assert.NoError(t, json.Unmarshal([]byte(data1), &bodies1))

	var (
		bodies0Map = make(map[common.Hash]*eth.ExecutionPayloadEnvelope)
		bodies1Map = make(map[common.Hash]*eth.ExecutionPayloadEnvelope)
	)
	for _, body := range bodies0 {
		bodies0Map[body.ExecutionPayload.BlockHash] = body
		t.Log("bodies0 content", "number", uint64(body.ExecutionPayload.BlockNumber), "hash", body.ExecutionPayload.BlockHash)
	}

	for _, body := range bodies1 {
		bodies1Map[body.ExecutionPayload.BlockHash] = body
		t.Log("bodies1 content", "number", uint64(body.ExecutionPayload.BlockNumber), "hash", body.ExecutionPayload.BlockHash)
	}

	data, err := os.ReadFile("preconf_blocks.json")
	assert.NoError(t, err)
	var bodies3 = make([]*eth.ExecutionPayloadEnvelope, 0, len(bodies0)+len(bodies1))
	assert.NoError(t, json.Unmarshal(data, &bodies3))

	ids0 := make([]common.Hash, len(bodies0)+10)
	ids1 := make([]common.Hash, len(bodies1)+10)
	for _, msg := range bodies3 {
		id := uint64(msg.ExecutionPayload.BlockNumber)
		if bodies0Map[msg.ExecutionPayload.BlockHash] != nil {
			ids0[id] = msg.ExecutionPayload.BlockHash
			log.Info("bodies0 message", "number", uint64(msg.ExecutionPayload.BlockNumber), "hash", msg.ExecutionPayload.BlockHash.TerminalString(), "parent", msg.ExecutionPayload.ParentHash.TerminalString())
		} else if bodies1Map[msg.ExecutionPayload.BlockHash] != nil {
			ids1[id] = msg.ExecutionPayload.BlockHash
			log.Info("bodies1 message", "number", uint64(msg.ExecutionPayload.BlockNumber), "hash", msg.ExecutionPayload.BlockHash.TerminalString(), "parent", msg.ExecutionPayload.ParentHash.TerminalString())
		} else {
			t.Logf("------------------------------")
		}
		assert.NoError(t, p2pNode.PublishL2Payload(ctx, msg))

		id0, hash0 := latestBlock(ids0)
		id1, hash1 := latestBlock(ids1)
		log.Info("latest block", "0_number", id0, "0_hash", hash0, "1_number", id1, "1_hash", hash1)
	}
	t.Logf("==============================")
}

func latestBlock(ids []common.Hash) (uint64, common.Hash) {
	var (
		id   uint64
		hash common.Hash
	)
	for i := 10; i < len(ids); i++ {
		if ids[i] == (common.Hash{}) {
			break
		}
		id, hash = uint64(i), ids[i]
	}
	return id, hash
}
